"ป๊อปอัปปลดล็อกและความสำเร็จ":"Unlock and achievement pop-ups",
"การ์ดกลางจอตอนปลดล็อกระบบใหม่หรือได้ความสำเร็จ (ปิดแล้วยังดูได้ในข่าว)":"A card in the middle of the screen when a new system unlocks or you earn an achievement (still visible in the news when off)",
