"สรุปรายได้ตอนกลับมาเล่น":"While-you-were-away summary",
"รายได้ระหว่างปิดเกมได้เท่าเดิมทั้งสองแบบ":"You earn the same while the game is closed either way",
"แค่ใส่ในข่าว":"Just add to the news",
"ความเร็วตอนเปิดเกม":"Speed when the game opens",
"ส่งซ่อมบำรุงอัตโนมัติ":"Automatic maintenance",
"ส่งเครื่องที่สภาพต่ำกว่า 50% เข้าซ่อมเอง วันละไม่เกิน 1 ลำต่อเส้นทาง":"Sends aircraft below 50% condition for repair by themselves, at most 1 per route per day",
"ปรับราคา ย้ายเครื่องจากเส้นที่ว่างไปเส้นที่ล้น และใส่เครื่องจอดว่างให้เอง":"Adjusts prices, moves aircraft from empty routes to overflowing ones, and assigns idle aircraft for you",
"ความเก่งของคู่แข่ง":"Rival skill",
"ความลื่นของแผนที่":"Map smoothness",
"อัตโนมัติ: วาดช้าลงเองเมื่อแผนที่มีเครื่องบินเยอะ · ประหยัดช่วยให้เครื่องไม่ร้อนและแบตอยู่นาน":"Auto: draws less often when the map has lots of aircraft · Saver keeps the device cool and the battery lasting",
"ลื่น":"Smooth",
