"ลดความเร็วเองเมื่อเกมคำนวณไม่ทัน":"Slow down automatically when the game can't keep up",
"ช่วงท้ายเกมที่มีเครื่องบินหลายร้อยลำ ความเร็ว 30× อาจทำให้จอค้าง เกมจะลดเป็น 10× หรือ 3× ให้เอง":"Late in the game with hundreds of aircraft, 30× can freeze the screen; the game will drop to 10× or 3× by itself",
"เสียงประกอบ":"Sound effects",
"เสียงตอนซื้อ ได้รางวัล ได้เงิน และมีประกาศ":"Sounds for buying, rewards, earning money and announcements",
